def parse_duration_seconds(spec: str) -> int:
    if not spec.strip():
        raise ValueError("Duration specification is empty or whitespace-only")

    units = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}
    total_seconds = 0

    for token in spec.split():
        if not token:
            continue

        if token[0] == '-':
            raise ValueError("Negative values are not allowed")

        if token[-1] not in units:
            raise ValueError(f"Unknown unit in token: {token}")

        value = token[:-1]
        if not value.isdigit():
            raise ValueError(f"Malformed token: {token}")

        total_seconds += int(value) * units[token[-1]]

    return total_seconds

import re

def mask_card_pan(pan: str) -> str:
    # Check if the input contains only digits and spaces/hyphens
    if not re.match(r'^\d[\d\s-]*\d$', pan):
        raise ValueError("Invalid characters in the card number")

    # Check if the length of the card number is 16 digits
    if len(re.sub(r'[\s-]', '', pan)) != 16:
        raise ValueError("Invalid length of the card number")

    # Mask the card number
    return re.sub(r'(?<=\d{4})\d(?=\d{4})', '*', pan)

